/**
 *  One review or conversation comment, flattened; the frontend groups inline
 *  comments into threads by `thread_id`.
 */
export type PrComment = {
	/**  REST `databaseId`; 0 for a conversation comment with no numeric id. */
	id: number,
	author: string,
	body: string,
	createdAt: string,
	/**  File path for an inline comment; `None` for a conversation comment. */
	path: string | null,
	/**  Line on the diff the comment anchors to. */
	line: number | null,
	/**  `RIGHT` (head) or `LEFT` (base) for an inline comment. */
	side: string | null,
	/**  The review-thread node id (GraphQL), shared by every comment in a thread. */
	threadId: string | null,
	/**  Whether the owning review thread is resolved. */
	isResolved: boolean,
};

/**  One commit on the PR branch. */
export type PrCommit = {
	oid: string,
	shortOid: string,
	headline: string,
	author: string,
};

/**  The full review payload for one PR. */
export type PrDetail = {
	summary: PrSummary,
	body: string,
	headSha: string,
	commits: PrCommit[],
	files: PrFile[],
	comments: PrComment[],
	checks: ChecksSummary | null,
	/**  True when the changed-file list was capped at `MAX_FILES`. */
	filesTruncated: boolean,
};

/**  One changed file in a PR (or a local branch diff). */
export type PrFile = {
	path: string,
	/**  The pre-rename path when `status` is `renamed`. */
	oldPath: string | null,
	/**  `added`, `modified`, `removed`, or `renamed`. */
	status: string,
	additions: number,
	deletions: number,
	/**  Raw unified diff for the file, fed to `DiffBlock` for rendering. */
	patch: string,
	hunks: DiffHunk[],
	/**  Whether the file's patch was omitted (binary, or too large). */
	patchTruncated: boolean,
};

/**  Result of comparing a locally-open PR against the current remote. */
export type PrFreshness = {
	stale: boolean,
	remoteHead: string,
	remoteUpdatedAt: string,
};

/**  A single open pull request in the PR picker. */
export type PrSummary = {
	number: number,
	title: string,
	author: string,
	/**  `OPEN`, `CLOSED`, or `MERGED`. */
	state: string,
	isDraft: boolean,
	baseRef: string,
	headRef: string,
	updatedAt: string,
	url: string,
};

/**
 *  One row in the sidebar: a real folder, a Codex-managed worktree, or a
 *  workspace hub standing in for several repositories.
 */
export type Project = {
	path: string,
	name: string,
	/**  "folder" | "worktree" | "multiProject". */
	kind: string,
	workspaceId: string | null,
	pinned: boolean,
	archived: boolean,
	/**
	 *  Whether the sidebar shows this project's threads. Missing preferences
	 *  default to true so new and pre-existing projects start expanded.
	 */
	expanded: boolean,
	threads: ThreadSummary[],
	/**  Free-form project instructions; empty string when none are stored. */
	instructions: string,
	/**  Attached, indexable folder/file sources for this project. */
	sources: StoredProjectSource[],
	members?: WorkspaceMember[],
	/**
	 *  When the project's newest thread was active, in Unix seconds, as the
	 *  app-server reports it (`Project.recencyAt`, unreleased Codex). `None`
	 *  on released Codex or a project with no threads; the sidebar then keeps
	 *  the stored order.
	 */
	recencyAt?: number | null,
};

