/**
 *  A request the app-server needs the user to answer, tagged by method.
 *  Only the ones Rust does not answer itself reach the frontend.
 */
export type ServerRequest = { method: "item/commandExecution/requestApproval"; params: CommandApprovalParams } | { method: "item/fileChange/requestApproval"; params: FileChangeApprovalParams } | { method: "item/permissions/requestApproval"; params: PermissionsApprovalParams } | { method: "item/tool/requestUserInput"; params: RequestUserInputParams } | { method: "mcpServer/elicitation/request"; params: ElicitationParams } | { method: "unknown"; params: UnknownNotification };

